 if(!canKarambitAttack())return false;
 const origin=camera.getWorldPosition(new THREE.Vector3()),direction=camera.getWorldDirection(new THREE.Vector3()),end=origin.clone().addScaledVector(direction,1.7);
 const candidates=meleePeople().filter(p=>p.rig.player.visible&&!p.knockdown.active()).map(p=>({p,center:p.rig.player.getWorldPosition(new THREE.Vector3()).add(new THREE.Vector3(0,.9,0))})).sort((a,b)=>a.center.distanceTo(origin)-b.center.distanceTo(origin));
